"""Pure tests; all generated bytes and identities below are NONCANONICAL fixtures."""
import copy
import hashlib
import importlib.util
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch
from types import SimpleNamespace


MODULE = Path(__file__).with_name("character_package_import.py")


def load_module():
    spec = importlib.util.spec_from_file_location("character_package_import", MODULE)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def fixture(root):
    """Not FBX/image content: validator-only bytes, never suitable for Unreal."""
    sources = []
    for sid, name, role in [("proof", "proof.json", "provenance"),
                            ("cloth", "cloth.fbx", "skeletal_mesh"),
                            ("light", "light.fbx", "skeletal_mesh"),
                            ("detail", "detail.fbx", "skeletal_mesh"),
                            ("color", "color.png", "texture")]:
        data = ("NONCANONICAL VALIDATOR FIXTURE " + sid).encode("ascii")
        (root / name).write_bytes(data)
        sources.append({"id": sid, "root": "fixture", "path": name,
                        "role": role, "version": "test-only-1",
                        "sha256": hashlib.sha256(data).hexdigest()})
    base = "/Game/NoWorld/Tests/Noncanonical"

    def wardrobe(wid, parts, bones):
        rows = []
        for sid in parts:
            name = "SK_" + sid
            rows.append({"id": sid, "source_id": sid,
                         "filename": sid + ".fbx",
                         "object_path": f"{base}/{name}.{name}",
                         "morph_targets": ["test_morph"],
                         "material_slots": [{"name": "test_slot", "material_id": "mat"}]})
        name = "SK_" + parts[0] + "_Skeleton"
        return {"id": wid, "version": "fixture-1", "expected_part_count": len(parts),
                "skeleton": {"mode": "create", "object_path": f"{base}/{name}.{name}",
                             "source_bone_count": len(bones) - 1,
                             "expected_bone_count": len(bones), "bone_names": bones},
                "parts": rows}

    return {"schema_version": "1.0", "package_id": "noncanonical_fixture",
            "character_id": "test_only_not_canon", "character_version": "fixture-1",
            "destination_root": base, "sources": sources,
            "provenance": [{"source_id": sid, "evidence_source_ids": ["proof"],
                            "statement": "Synthetic validator fixture only"}
                           for sid in ("cloth", "light", "detail", "color")],
            "settings": {"uniform_scale": 1.0, "convert_scene": True,
                         "convert_scene_unit": True, "force_front_x_axis": False,
                         "translation": [0, 0, 0], "rotation": [0, 0, 0]},
            "textures": [{"id": "tex", "source_id": "color",
                          "object_path": f"{base}/T_color.T_color",
                          "srgb": True, "compression": "default"}],
            "materials": [{"id": "mat", "object_path": f"{base}/M_test.M_test",
                           "two_sided": False, "blend_mode": "opaque",
                           "textures": {"base_color": "tex"}}],
            "wardrobes": [wardrobe("test_cloth", ["cloth"], ["root", "joint", "extra"]),
                          wardrobe("test_light", ["light", "detail"], ["root", "joint"])]}


class CharacterPackageTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if not MODULE.is_file():
            raise AssertionError("character package validator has not been implemented")
        cls.mod = load_module()

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.doc = fixture(self.root)
        self.roots = {"fixture": self.root}

    def validate(self, doc=None):
        return self.mod.validate_manifest(self.doc if doc is None else doc, self.roots)

    def reject(self, mutate):
        mutate(self.doc)
        with self.assertRaises(self.mod.ValidationError):
            self.validate()

    def test_fixture_keeps_distinct_wardrobe_part_and_bone_counts(self):
        plan = self.validate()
        self.assertEqual([w["expected_part_count"] for w in plan["manifest"]["wardrobes"]], [1, 2])
        self.assertEqual([w["skeleton"]["expected_bone_count"]
                          for w in plan["manifest"]["wardrobes"]], [3, 2])
        self.assertEqual(len(plan["assets"]), 7)
        self.assertEqual(self.doc, plan["manifest"])

    def test_hashes_use_exact_bytes_and_detect_source_changes(self):
        (self.root / "cloth.fbx").write_bytes(b"modified")
        with self.assertRaisesRegex(self.mod.ValidationError, "SHA256"):
            self.validate()

    def test_line_endings_are_not_normalized_for_hashing(self):
        data = (self.root / "proof.json").read_bytes()
        (self.root / "proof.json").write_bytes(data + b"\r\n")
        with self.assertRaisesRegex(self.mod.ValidationError, "SHA256"):
            self.validate()

    def test_rejects_unsafe_source_paths(self):
        for path in ("../cloth.fbx", "a/../cloth.fbx", "/cloth.fbx", "C:/cloth.fbx",
                     "a\\cloth.fbx", "//server/file", "cloth.fbx:stream", "./cloth.fbx",
                     "a//cloth.fbx", "cloth.fbx.", "CON.fbx"):
            with self.subTest(path=path):
                doc = copy.deepcopy(self.doc)
                doc["sources"][1]["path"] = path
                with self.assertRaises(self.mod.ValidationError):
                    self.validate(doc)

    def test_explicit_roots_are_required(self):
        with self.assertRaises(self.mod.ValidationError):
            self.mod.validate_manifest(self.doc, {})
        with self.assertRaises(self.mod.ValidationError):
            self.mod.validate_manifest(self.doc, {"fixture": Path("relative")})

    def test_symlink_cannot_escape_source_root(self):
        with tempfile.TemporaryDirectory() as other:
            target = Path(other) / "outside.fbx"
            target.write_bytes((self.root / "cloth.fbx").read_bytes())
            link = self.root / "escape.fbx"
            try:
                link.symlink_to(target)
            except OSError as exc:
                self.skipTest("OS does not permit symlink creation: " + str(exc))
            self.doc["sources"][1]["path"] = "escape.fbx"
            self.doc["wardrobes"][0]["parts"][0]["filename"] = "escape.fbx"
            with self.assertRaises(self.mod.ValidationError):
                self.validate()

    def test_strict_game_object_namespace_and_names(self):
        for path in ("/Engine/A.A", "/GameX/A.A", "/game/A.A", "/Game/A/../B.B",
                     "/Game/A.A:Sub", "SkeletalMesh'/Game/A.A'", "/Game/A.B",
                     "/Game/Other/A.A", "/Game/A A.A A", "/Game/A"):
            with self.subTest(path=path):
                doc = copy.deepcopy(self.doc)
                doc["textures"][0]["object_path"] = path
                with self.assertRaises(self.mod.ValidationError):
                    self.validate(doc)

    def test_rejects_duplicate_ids_paths_packages_and_sources(self):
        mutations = [
            lambda d: d["sources"].append(copy.deepcopy(d["sources"][0])),
            lambda d: d["sources"][2].update(root="fixture", path="cloth.fbx"),
            lambda d: d["wardrobes"][1].update(id="test_cloth"),
            lambda d: d["textures"][0].update(object_path=d["materials"][0]["object_path"]),
            lambda d: d["textures"][0].update(object_path="/Game/NoWorld/Tests/Noncanonical/m_test.m_test"),
        ]
        for mutation in mutations:
            with self.subTest(mutation=mutation):
                doc = copy.deepcopy(self.doc)
                mutation(doc)
                with self.assertRaises(self.mod.ValidationError):
                    self.validate(doc)

    def test_rejects_malformed_contracts(self):
        mutations = [
            lambda d: d.update(schema_version="2.0"),
            lambda d: d.update(run_script="arbitrary.py"),
            lambda d: d["sources"][0].update(sha256="x" * 64),
            lambda d: d["sources"][0].update(role="script"),
            lambda d: d["sources"][0].pop("version"),
            lambda d: d["wardrobes"][0].update(expected_part_count=True),
            lambda d: d["wardrobes"][0].update(expected_part_count=2),
            lambda d: d["wardrobes"][0]["skeleton"].update(expected_bone_count=9),
            lambda d: d["wardrobes"][0]["skeleton"].update(bone_names=["root", "root", "extra"]),
            lambda d: d["settings"].update(uniform_scale=0),
            lambda d: d["settings"].update(uniform_scale=float("nan")),
            lambda d: d["settings"].update(uniform_scale=10 ** 400),
            lambda d: d["settings"].update(rotation=[0, 0]),
            lambda d: d["settings"].update(convert_scene=1),
            lambda d: d["wardrobes"][0]["parts"][0].update(filename="different.fbx"),
            lambda d: d["wardrobes"][0]["parts"][0].update(morph_targets=["same", "same"]),
        ]
        for mutation in mutations:
            with self.subTest(mutation=mutation):
                doc = copy.deepcopy(self.doc)
                mutation(doc)
                with self.assertRaises(self.mod.ValidationError):
                    self.validate(doc)

    def test_reference_integrity_and_provenance_are_required(self):
        mutations = [
            lambda d: d["textures"][0].update(source_id="cloth"),
            lambda d: d["materials"][0]["textures"].update(base_color="missing"),
            lambda d: d["wardrobes"][0]["parts"][0]["material_slots"][0].update(material_id="missing"),
            lambda d: d["provenance"][0].update(evidence_source_ids=["cloth"]),
            lambda d: d["provenance"].pop(),
            lambda d: d["wardrobes"][0]["parts"][0].update(source_id="missing"),
            lambda d: d["wardrobes"][0]["skeleton"].update(object_path=d["textures"][0]["object_path"]),
        ]
        for mutation in mutations:
            with self.subTest(mutation=mutation):
                doc = copy.deepcopy(self.doc)
                mutation(doc)
                with self.assertRaises(self.mod.ValidationError):
                    self.validate(doc)

    def test_skeleton_create_name_is_exact_and_reuse_is_explicit(self):
        self.reject(lambda d: d["wardrobes"][0]["skeleton"].update(
            object_path="/Game/NoWorld/Tests/Noncanonical/Other.Other"))
        self.doc["wardrobes"][0]["skeleton"]["mode"] = "reuse"
        self.doc["wardrobes"][0]["skeleton"]["object_path"] = "/Game/Explicit/Shared.Shared"
        self.assertEqual(self.validate()["external_skeletons"], ["/Game/Explicit/Shared.Shared"])

    def test_dry_run_never_imports_unreal_and_is_deterministic(self):
        real_import = __import__

        def guarded(name, *args, **kwargs):
            if name == "unreal":
                raise AssertionError("dry run imported Unreal")
            return real_import(name, *args, **kwargs)

        with patch("builtins.__import__", side_effect=guarded):
            a = self.mod.import_package(self.doc, self.roots, dry_run=True)
            b = self.mod.import_package(self.doc, self.roots, dry_run=True)
        self.assertEqual(a, b)
        self.assertEqual(a["status"], "DRY_RUN_VALIDATED")
        self.assertFalse(a["native_verified"])
        self.assertEqual(len(a["sources"]), 5)

    def test_object_key_order_does_not_change_manifest_fingerprint(self):
        # Object key order is irrelevant; array order intentionally defines the plan.
        a = self.validate()
        b = self.validate(dict(reversed(list(self.doc.items()))))
        self.assertEqual(a["manifest_sha256"], b["manifest_sha256"])

    def test_source_role_extensions_are_checked_before_any_import(self):
        self.reject(lambda d: d["textures"][0].update(source_id="proof"))

    def test_snapshot_rechecks_sources_after_validation(self):
        plan = self.validate()
        (self.root / "cloth.fbx").write_bytes(b"changed after planning")
        with tempfile.TemporaryDirectory() as directory:
            with self.assertRaisesRegex(self.mod.ValidationError, "SHA256"):
                self.mod._stage_sources(plan, Path(directory))

    def test_snapshots_copy_only_import_sources_and_keep_verified_bytes(self):
        plan = self.validate()
        with tempfile.TemporaryDirectory() as directory:
            staged = self.mod._stage_sources(plan, Path(directory))
            self.assertEqual(set(staged), {"cloth", "light", "detail", "color"})
            self.assertEqual(staged["cloth"].read_bytes(), b"NONCANONICAL VALIDATOR FIXTURE cloth")
            (self.root / "cloth.fbx").write_bytes(b"changed later")
            self.assertEqual(staged["cloth"].read_bytes(), b"NONCANONICAL VALIDATOR FIXTURE cloth")

    def test_root_types_fail_as_validation_errors(self):
        for roots in (None, [], {"fixture": None}, {"fixture": 123}):
            with self.subTest(roots=roots), self.assertRaises(self.mod.ValidationError):
                self.mod.validate_manifest(self.doc, roots)

    def test_invalid_native_request_fails_before_importing_unreal(self):
        self.doc["sources"][1]["sha256"] = "0" * 64
        with patch.dict(sys.modules, {"unreal": None}):
            with self.assertRaises(self.mod.ValidationError):
                self.mod.import_package(self.doc, self.roots, dry_run=False)

    def test_native_failure_exposes_a_failed_provenance_receipt(self):
        with patch.dict(sys.modules, {"unreal": None}):
            with self.assertRaises(self.mod.ImportFailure) as raised:
                self.mod.import_package(self.doc, self.roots, dry_run=False)
        receipt = raised.exception.receipt
        self.assertEqual(receipt["status"], "FAILED")
        self.assertFalse(receipt["native_verified"])
        self.assertEqual(len(receipt["sources"]), 5)
        self.assertIn("error", receipt)

    def test_native_skeleton_rejects_extra_missing_or_reordered_bones(self):
        contract = self.doc["wardrobes"][0]["skeleton"]
        for names in (["root", "joint"], ["root", "joint", "extra", "unwanted"],
                      ["root", "extra", "joint"]):
            api = SimpleNamespace(AnimPoseExtensions=SimpleNamespace(get_bone_names=lambda pose: pose))
            asset = SimpleNamespace(get_reference_pose=lambda: names)
            with self.subTest(names=names), self.assertRaises(self.mod.ValidationError):
                self.mod._verify_skeleton(api, asset, contract)

    def test_import_rejects_an_undeclared_native_factory_output(self):
        class Task:
            def set_editor_property(self, key, value):
                pass

            def get_editor_property(self, key):
                return ["/Game/NoWorld/Tests/Noncanonical/SK_cloth.SK_cloth",
                        "/Game/Unlisted/Unexpected.Unexpected"]

        api = SimpleNamespace(AssetImportTask=Task, AssetToolsHelpers=SimpleNamespace(
            get_asset_tools=lambda: SimpleNamespace(import_asset_tasks=lambda tasks: None)))
        target = "/Game/NoWorld/Tests/Noncanonical/SK_cloth.SK_cloth"
        with self.assertRaises(self.mod.ValidationError):
            self.mod._task(api, self.root / "cloth.fbx", target, object(), object(), [target])

    def test_reuse_contracts_disagree_before_loading_unreal(self):
        for wardrobe in self.doc["wardrobes"]:
            wardrobe["skeleton"].update(mode="reuse", object_path="/Game/Explicit/Shared.Shared")
        with self.assertRaisesRegex(self.mod.ValidationError, "contracts disagree"):
            self.validate()

    def test_provenance_extension_never_enables_execution(self):
        # A script-shaped evidence file is still opaque bytes; its contents are never run.
        data = b"raise RuntimeError('must never execute')\n"
        (self.root / "evidence.py").write_bytes(data)
        self.doc["sources"][0].update(path="evidence.py", sha256=hashlib.sha256(data).hexdigest())
        receipt = self.mod.import_package(self.doc, self.roots)
        self.assertEqual(receipt["status"], "DRY_RUN_VALIDATED")

    def test_malformed_root_documents_are_rejected(self):
        for value in (None, [], True, "manifest", 42, {"schema_version": "1.0"}):
            with self.subTest(value=value), self.assertRaises(self.mod.ValidationError):
                self.validate(value) if value is not None else self.mod.validate_manifest(value, self.roots)

    def test_material_channel_contracts_reject_inconsistent_settings(self):
        mutations = [
            lambda d: d["textures"][0].update(compression="normalmap"),
            lambda d: d["materials"][0].update(blend_mode="masked"),
            lambda d: d["materials"][0]["textures"].update(opacity_mask="tex"),
            lambda d: d["materials"][0]["textures"].update(normal="tex"),
            lambda d: d["materials"][0]["textures"].update(roughness="tex"),
        ]
        for mutation in mutations:
            doc = copy.deepcopy(self.doc)
            mutation(doc)
            with self.subTest(mutation=mutation), self.assertRaises(self.mod.ValidationError):
                self.validate(doc)

    def test_import_task_uses_typed_destination_and_disables_overwrite(self):
        # Narrow boundary double: exercise our task configuration without Unreal.
        tasks = []

        class Task:
            def __init__(self):
                self.properties = {}

            def set_editor_property(self, key, value):
                self.properties[key] = value

            def get_editor_property(self, key):
                return self.properties[key]

        target = "/Game/NoWorld/Tests/Noncanonical/SK_cloth.SK_cloth"

        def run(import_tasks):
            tasks.extend(import_tasks)
            import_tasks[0].properties["imported_object_paths"] = [target]

        api = SimpleNamespace(AssetImportTask=Task, AssetToolsHelpers=SimpleNamespace(
            get_asset_tools=lambda: SimpleNamespace(import_asset_tasks=run)))
        factory, options = object(), object()
        self.mod._task(api, self.root / "cloth.fbx", target, factory, options, [target])
        props = tasks[0].properties
        self.assertIs(type(props["destination_path"]), str)
        self.assertEqual(props["destination_path"], "/Game/NoWorld/Tests/Noncanonical")
        self.assertEqual(props["destination_name"], "SK_cloth")
        self.assertIs(props["factory"], factory)
        self.assertIs(props["options"], options)
        self.assertFalse(props["replace_existing"])
        self.assertFalse(props["replace_existing_settings"])
        self.assertFalse(props["save"])
        self.assertFalse(props["async_"])
        self.assertTrue(props["automated"])

    def test_schema_is_independently_valid_draft_2020_12_when_available(self):
        try:
            import jsonschema
        except ImportError:
            self.skipTest("Optional independent jsonschema checker unavailable")
        schema = json.loads((MODULE.parents[2] / "schemas/character_asset_package.schema.json").read_text())
        jsonschema.Draft202012Validator.check_schema(schema)
        jsonschema.Draft202012Validator(schema).validate(self.doc)
        self.doc["wardrobes"][0]["expected_part_count"] = True
        with self.assertRaises(jsonschema.ValidationError):
            jsonschema.Draft202012Validator(schema).validate(self.doc)

    def test_existing_asset_conflicts_fail_without_replacement(self):
        plan = self.validate()
        path = plan["assets"][0]["object_path"]
        with self.assertRaises(self.mod.ValidationError):
            self.mod.check_existing_assets(plan, {path: {}}, "reject")
        with self.assertRaises(self.mod.ValidationError):
            self.mod.check_existing_assets(plan, {path: {"manifest_sha256": "0" * 64}}, "preserve_verified")

    def test_preservation_requires_complete_matching_receipts(self):
        plan = self.validate()
        inventory = {a["object_path"]: {"manifest_sha256": plan["manifest_sha256"],
                                       "kind": a["kind"]} for a in plan["assets"]}
        self.assertEqual(self.mod.check_existing_assets(plan, inventory, "preserve_verified"), "preserve")
        inventory.pop(next(iter(inventory)))
        with self.assertRaises(self.mod.ValidationError):
            self.mod.check_existing_assets(plan, inventory, "preserve_verified")
        with self.assertRaises(self.mod.ValidationError):
            self.mod.check_existing_assets(plan, {}, "overwrite")

    def test_json_duplicate_keys_and_nonfinite_numbers_are_rejected(self):
        for data in ('{"schema_version":"1.0","schema_version":"2.0"}', '{"value":NaN}'):
            path = self.root / "manifest.json"
            path.write_text(data, encoding="utf-8")
            with self.assertRaises(self.mod.ValidationError):
                self.mod.load_manifest(path)

    def test_cli_dry_run_and_invalid_manifest_exit_codes(self):
        path = self.root / "manifest.json"
        path.write_text(json.dumps(self.doc), encoding="utf-8")
        args = [sys.executable, "-B", str(MODULE), str(path), "--source-root", f"fixture={self.root}"]
        result = subprocess.run(args, text=True, capture_output=True, check=False)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(json.loads(result.stdout)["status"], "DRY_RUN_VALIDATED")
        (self.root / "cloth.fbx").write_bytes(b"changed")
        result = subprocess.run(args, text=True, capture_output=True, check=False)
        self.assertEqual(result.returncode, 2)
        self.assertIn("SHA256", result.stderr)


if __name__ == "__main__":
    unittest.main()
